import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

type Case = {
  label: string;
  kind: string;
  status: number;
  code: string;
  file: { name: string; mimeType: string; buffer: Buffer };
};

const cases: Case[] = [
  {
    label: "an empty file",
    kind: "w9",
    status: 422,
    code: "empty_file",
    file: { name: "w9-empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) },
  },
  {
    label: "a file of exactly 10 MiB + 1",
    kind: "w9",
    status: 413,
    code: "file_too_large",
    file: {
      name: "w9-oversized.pdf",
      mimeType: "application/pdf",
      buffer: Buffer.alloc(TEN_MIB + 1, 0x41),
    },
  },
  {
    label: "a .exe file",
    kind: "w9",
    status: 415,
    code: "unsupported_type",
    file: {
      name: "installer.exe",
      mimeType: "application/x-msdownload",
      buffer: Buffer.from("MZ\x90\x00 fake executable payload"),
    },
  },
  {
    label: "a valid text file with an unknown kind",
    kind: "passport",
    status: 422,
    code: "validation_error",
    file: {
      name: "notes.txt",
      mimeType: "text/plain",
      buffer: Buffer.from("Vendor passport notes, plain text."),
    },
  },
];

test.describe("Upload vendor documents: reject invalid uploads", () => {
  for (const c of cases) {
    test(
      `rejects ${c.label} with status ${c.status} and code ${c.code}`,
      { tag: "@DOC-04" },
      async ({ apiAs }) => {
        // Arrange: a vendor in draft status owned by the member's tenant
        const member = await apiAs("member");
        const created = await member.post("/api/vendors", {
          data: {
            name: uniqueName("DOC04 Vendor"),
            category: "services",
            contact_email: `doc04-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor.test`,
          },
        });
        expect(created.status()).toBe(201);
        const vendor = await created.json();
        expect(vendor.status).toBe("draft");

        // Act: upload the invalid document
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: c.kind,
            file: c.file,
          },
        });

        // Assert
        expect(response.status()).toBe(c.status);
        const body = await response.json();
        expect(body.error.code).toBe(c.code);
      },
    );
  }
});
